; pi_spigot.asm - generated by gen_pi_spigot.py, do not edit by hand
; Placard CPU benchmark: Rabinowitz & Wagon spigot, 1000 digits of pi,
; centered on the screen, timed with the line read, repeated every 10 s.
; See gen_pi_spigot.py for the method, timer and memory map.
;
;     python3 placard_sim.py pi_spigot.asm --run --max-steps 2000000000 --stop-at pause --png pi.png
;
; Date: 10/20/2026

#include "placard.asm"

#addr 0x0000
reset:
    ld   init >> 8, y
    jmp  init

#addr 0x0080
font:      ; 0-9, ".", space and "s", 8 bytes each, leftmost pixel in bit 0
    #d8 0x0E, 0x11, 0x19, 0x15, 0x13, 0x11, 0x0E, 0x00
    #d8 0x04, 0x06, 0x04, 0x04, 0x04, 0x04, 0x0E, 0x00
    #d8 0x0E, 0x11, 0x10, 0x08, 0x04, 0x02, 0x1F, 0x00
    #d8 0x1F, 0x08, 0x04, 0x08, 0x10, 0x11, 0x0E, 0x00
    #d8 0x08, 0x0C, 0x0A, 0x09, 0x1F, 0x08, 0x08, 0x00
    #d8 0x1F, 0x01, 0x0F, 0x10, 0x10, 0x11, 0x0E, 0x00
    #d8 0x0C, 0x02, 0x01, 0x0F, 0x11, 0x11, 0x0E, 0x00
    #d8 0x1F, 0x10, 0x08, 0x04, 0x02, 0x02, 0x02, 0x00
    #d8 0x0E, 0x11, 0x11, 0x0E, 0x11, 0x11, 0x0E, 0x00
    #d8 0x0E, 0x11, 0x11, 0x1E, 0x10, 0x08, 0x06, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x06, 0x06, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x1E, 0x01, 0x0E, 0x10, 0x0F, 0x00

#addr 0x0100
tsync:
    ; start the timer at the top of a frame: wait for the line read to wrap
    ld   ret_1, ac
    ld   ac, [0x32]
    ld   ret_1 >> 8, ac
    ld   ac, [0x33]
    ld   poll >> 8, y
    jmp  poll
ret_1:
sync:
    ld   0x00, ac
    ld   ac, [0x2E]
    ld   ret_2, ac
    ld   ac, [0x32]
    ld   ret_2 >> 8, ac
    ld   ac, [0x33]
    ld   poll >> 8, y
    jmp  poll
ret_2:
    ld   [0x2E], ac
    beq  sync
    ld   ret_3, ac
    ld   ac, [0x32]
    ld   ret_3 >> 8, ac
    ld   ac, [0x33]
    ld   tclear >> 8, y
    jmp  tclear
ret_3:
    ; a[i] = 2: low limb pages = 2, high limb pages = 0
    ld   0x09, ac
    ld   ac, [0x27]
fill_pg:
    ld   ret_4, ac
    ld   ac, [0x32]
    ld   ret_4 >> 8, ac
    ld   ac, [0x33]
    ld   poll >> 8, y
    jmp  poll
ret_4:
    ld   [0x27], y
    clr  ac
fill_b:
    ld   ac, x
    ld   0x02, [y,x]
    inc
    bne  fill_b
    ld   [0x27], ac
    add  0x0E, y
    clr  ac
fill_h:
    ld   ac, x
    ld   0x00, [y,x]
    inc
    bne  fill_h
    ld   [0x27], ac
    inc
    ld   ac, [0x27]
    sub  0x17, ac
    bne  fill_pg
    ; output state
    ld   0x00, ac
    ld   ac, [0x1B]
    ld   0x00, ac
    ld   ac, [0x1C]
    ld   0x01, ac
    ld   ac, [0x1D]
    ld   0x01, ac
    ld   ac, [0x20]
    ld   0x7C, ac
    ld   ac, [0x21]
    ld   0xB8, ac
    ld   ac, [0x22]
    ld   0x00, ac
    ld   ac, [0x24]
    ld   0x34, ac
    ld   ac, [0x23]
    ld   0xE8, ac
    ld   ac, [0x2A]
    ld   0x03, ac
    ld   ac, [0x2B]
    ; ---- one digit per pass ----
outer:
    ld   0x00, ac
    ld   ac, [0x15]
    ld   0x0D, ac
    ld   ac, [0x18]
    ld   0x06, ac
    ld   ac, [0x19]
    ld   0x16, ac
    ld   ac, [0x1A]
    ld   0x0B, ac
    ld   ac, [0x3A]
    ld   0x1A, ac
    ld   ac, [0x3B]
    ld   0x00, ac
    ld   ac, [0x3C]
    ld   0x16, ac
    ld   ac, [0x3D]
    ld   0x34, ac
    ld   ac, [0x3E]
    ld   0x00, ac
    ld   ac, [0x3F]
    ld   0x2C, ac
    ld   ac, [0x40]
    ld   0x68, ac
    ld   ac, [0x41]
    ld   0x00, ac
    ld   ac, [0x42]
    ld   0x58, ac
    ld   ac, [0x43]
    ld   0xD0, ac
    ld   ac, [0x44]
    ld   0x00, ac
    ld   ac, [0x45]
    ld   0xB0, ac
    ld   ac, [0x46]
    ld   0xA0, ac
    ld   ac, [0x47]
    ld   0x01, ac
    ld   ac, [0x48]
    ld   inner >> 8, y
    jmp  inner

#addr 0x01D4
tclear:
    ; timer = 0, frame addend = 16800 us, step addend = 128 us
    ld   0x28, ac
tcl:
    add  0x50, x
    ld   0x00, [x]
    sub  1, ac
    bcc  tcl
    ld   8, ac
    ld   ac, [0x62]
    ld   6, ac
    ld   ac, [0x63]
    ld   1, ac
    ld   ac, [0x64]
    ld   8, ac
    ld   ac, [0x70]
    ld   2, ac
    ld   ac, [0x71]
    ld   1, ac
    ld   ac, [0x72]
    ld   [0x33], y
    jmp  [0x32]

#addr 0x0200
emit:
    ; draw glyph [dig] at the cursor, then a "." after the first digit
    ld   [0x1F], ac
    shl
    shl
    shl
    or   0x80, ac
    ld   ac, [0x25]
    ld   [0x22], ac
    ld   ac, [0x26]
    ld   [0x25], ac
    add  0, x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x27]
    ld   [0x26], ac
    add  0, x
    ld   [0x21], y
    ld   [0x27], ac
    ld   ac, [y,x]
    ld   [0x25], ac
    add  1, x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x27]
    ld   [0x26], ac
    add  1, x
    ld   [0x21], y
    ld   [0x27], ac
    ld   ac, [y,x]
    ld   [0x25], ac
    add  2, x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x27]
    ld   [0x26], ac
    add  2, x
    ld   [0x21], y
    ld   [0x27], ac
    ld   ac, [y,x]
    ld   [0x25], ac
    add  3, x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x27]
    ld   [0x26], ac
    add  3, x
    ld   [0x21], y
    ld   [0x27], ac
    ld   ac, [y,x]
    ld   [0x25], ac
    add  4, x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x27]
    ld   [0x26], ac
    add  4, x
    ld   [0x21], y
    ld   [0x27], ac
    ld   ac, [y,x]
    ld   [0x25], ac
    add  5, x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x27]
    ld   [0x26], ac
    add  5, x
    ld   [0x21], y
    ld   [0x27], ac
    ld   ac, [y,x]
    ld   [0x25], ac
    add  6, x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x27]
    ld   [0x26], ac
    add  6, x
    ld   [0x21], y
    ld   [0x27], ac
    ld   ac, [y,x]
    ld   [0x25], ac
    add  7, x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x27]
    ld   [0x26], ac
    add  7, x
    ld   [0x21], y
    ld   [0x27], ac
    ld   ac, [y,x]
    ; next character cell
    ld   [0x21], ac
    add  2, ac
    ld   ac, [0x21]
    ld   [0x23], ac
    dec
    ld   ac, [0x23]
    bne  advd
    ld   0x32, ac
    ld   ac, [0x23]
    ld   [0x22], ac
    add  8, ac
    ld   ac, [0x22]
    bne  nlw
    ld   0x01, ac
    ld   ac, [0x24]
nlw:
    ld   0x80, ac
    add  [0x24], ac
    ld   ac, [0x21]
advd:
    ld   [0x20], ac
    beq  eret
    ld   0x00, ac
    ld   ac, [0x20]
    ld   0x0A, ac
    ld   ac, [0x1F]
    bra  emit
eret:
    ld   [0x29], y
    jmp  [0x28]

#addr 0x02D3
main:
    ; clear video RAM 6000-FFFF (pixels off)
    ld   0x60, ac
    ld   ac, [0x27]
clr_pg:
    ld   [0x27], y
    clr  ac
clr_b:
    ld   ac, x
    ld   0x00, [y,x]
    inc
    bne  clr_b
    ld   [0x27], ac
    inc
    ld   ac, [0x27]
    bne  clr_pg
    ld   clr_m >> 8, y
    jmp  clr_m

#addr 0x0300
last_i:
    ; x = 10 * a[1] + q, a[1] = x mod 10, q = x div 10 (x <= 110)
    ld   0x09, y
    ld   0x01, x
    ld   [y,x], ac
    shl
    ld   ac, [0x13]
    shl
    shl
    add  [0x13], ac
    add  [0x15], ac
    ld   ac, [0x10]
    clr  ac
    ld   ac, [0x15]
d10:
    ld   [0x10], ac
    sub  10, ac
    blt  d10done
    ld   ac, [0x10]
    ld   [0x15], ac
    inc
    ld   ac, [0x15]
    bra  d10
d10done:
    ld   [0x10], ac
    ld   ac, [y,x]
    ; predigit handling
    ld   [0x15], ac
    sub  9, ac
    bne  not9
    ld   [0x1C], ac
    inc
    ld   ac, [0x1C]
    bra  next
not9:
    sub  1, ac
    bne  normal
    ; q = 10: held digit + 1, then the held 9s become 0s
    ld   [0x1B], ac
    inc
    ld   ac, [0x1F]
    ld   ret_29, ac
    ld   ac, [0x28]
    ld   ret_29 >> 8, ac
    ld   ac, [0x29]
    ld   emit >> 8, y
    jmp  emit
ret_29:
    ld   0x00, ac
    ld   ac, [0x1E]
    ld   0x00, ac
    ld   ac, [0x1B]
    bra  flush
normal:
    ld   [0x1D], ac
    bne  nofirst
    ld   [0x1B], ac
    ld   ac, [0x1F]
    ld   ret_30, ac
    ld   ac, [0x28]
    ld   ret_30 >> 8, ac
    ld   ac, [0x29]
    ld   emit >> 8, y
    jmp  emit
ret_30:
nofirst:
    ld   0x00, ac
    ld   ac, [0x1D]
    ld   [0x15], ac
    ld   ac, [0x1B]
    ld   0x09, ac
    ld   ac, [0x1E]
flush:
    ld   [0x1C], ac
    beq  next
    dec
    ld   ac, [0x1C]
    ld   [0x1E], ac
    ld   ac, [0x1F]
    ld   ret_31, ac
    ld   ac, [0x28]
    ld   ret_31 >> 8, ac
    ld   ac, [0x29]
    ld   emit >> 8, y
    jmp  emit
ret_31:
    bra  flush
next:
    ; digits left
    ld   [0x2A], ac
    dec
    ld   ac, [0x2A]
    bcc  jok
    ld   [0x2B], ac
    dec
    ld   ac, [0x2B]
jok:
    ld   [0x2A], ac
    or   [0x2B], ac
    beq  finish
    ld   outer >> 8, y
    jmp  outer
finish:
    ld   [0x1B], ac
    ld   ac, [0x1F]
    ld   ret_32, ac
    ld   ac, [0x28]
    ld   ret_32 >> 8, ac
    ld   ac, [0x29]
    ld   emit >> 8, y
    jmp  emit
ret_32:
    ld   stop >> 8, y
    jmp  stop

#addr 0x03BA
dadd:
    ; timer digits at 0x50 += addend digits at 0x50 + [doff], decimal
    clr  ac
    ld   ac, [0x30]
    ld   ac, [0x37]
dl:
    ld   [0x37], ac
    add  0x50, x
    ld   [x], ac
    add  [0x30], ac
    ld   ac, [0x31]
    ld   [0x37], ac
    add  [0x2F], ac
    add  0x50, x
    ld   [x], ac
    add  [0x31], ac
    ld   ac, [0x31]
    ld   [0x37], ac
    add  0x50, x
    ld   [0x31], ac
    sub  10, ac
    blt  dlt
    ld   ac, [x]
    ld   1, ac
    bra  dn
dlt:
    ld   [0x31], ac
    ld   ac, [x]
    clr  ac
dn:
    ld   ac, [0x30]
    ld   [0x37], ac
    inc
    ld   ac, [0x37]
    sub  9, ac
    bne  dl
    ld   [0x35], y
    jmp  [0x34]

#addr 0x0400
inner:
    ; a[i] -> al, ah (X = px is also the low byte of i)
    ld   [0x19], x
    ld   [0x1A], y
    ld   [y,x], ac
    ld   ac, [0x16]
    ld   [0x1A], ac
    add  0x0E, y
    ld   [y,x], ac
    ld   ac, [0x17]
    ; q * i: x0 = T[q][il].lo, t0 = T[q][il].hi, x1 = T[q][ih].lo (q * ih < 256)
    ld   [0x15], ac
    add  0x25, y
    ld   [y,x], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    add  0x38, y
    ld   [y,x], ac
    ld   ac, [0x13]
    ld   [0x15], ac
    add  0x25, y
    ld   [0x18], x
    ld   [y,x], ac
    ld   ac, [0x11]
    ; + 10 * al: x0 += T[10][al].lo, t0 += T[10][al].hi + carry (< 256)
    ld   [0x16], x
    ld   0x2F, y
    ld   [y,x], ac
    add  [0x10], ac
    ld   ac, [0x10]
    ld   0x42, y
    ld   [y,x], ac
    bcc  qi0
    inc
qi0:
    add  [0x13], ac
    add  [0x11], ac
    ld   ac, [0x11]
    ; + 2560 * ah: x2 = T[10][ah].hi + carries, x1 += T[10][ah].lo
    ld   [0x17], x
    ld   [y,x], ac
    bcc  qi1
    inc
qi1:
    ld   ac, [0x12]
    ld   0x2F, y
    ld   [y,x], ac
    add  [0x11], ac
    ld   ac, [0x11]
    bcc  qi2
    ld   [0x12], ac
    inc
    ld   ac, [0x12]
qi2:
    ; x div (2i - 1), q in zero page (X is not a source)
    clr  ac
    ld   ac, [0x15]
    ; k = 4
    ld   [0x10], ac
    sub  [0x46], ac
    ld   ac, [0x13]
    ld   [0x11], ac
    bcc  ka_5
    dec
    bcs  kz_6
ka_5:
    sub  [0x47], ac
    ld   ac, [0x14]
    ld   [0x12], ac
    bcc  kb_8
    dec
    bcs  ks_7
kb_8:
    sub  [0x48], ac
    bcs  ks_7
    ld   ac, [0x12]
    ld   [0x14], ac
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   0x10, ac
    ld   ac, [0x15]
    bra  ks_7
kz_6:
    ; x1 was 0 and borrowed: t1 = FF - D_41, borrow into x2
    ld   [0x47], ac
    not
    ld   ac, [0x14]
    ld   [0x12], ac
    dec
    bcs  ks_7
    bra  kb_8
ks_7:
    ld   div2 >> 8, y
    jmp  div2

#addr 0x0496
hk_done:
    ld 0x5D, y
    ld 0x00, x
    ld [y,x], ac
    xor 0x4D, ac
    bne hkd_ret
    ld 0x01, x
    ld [y,x], ac
    xor 0x4E, ac
    bne hkd_ret
    ld 0x02, x
    ld [y,x], ac
    xor 0x55, ac
    bne hkd_ret
    ld 0x03, x
    ld [y,x], ac
    beq hkd_next    ; rotating: next program
hkd_ret:
    ld [0x39], y
    jmp [0x38]
hkd_next:
    ld 2, ac
    ld 0x09, x
    ld ac, [y,x]
    jmp 0x20    ; the menu's exit code (RAM x5D20)
hk_hold:
    ld 0x5D, y
    ld 0x00, x
    ld [y,x], ac
    xor 0x4D, ac
    bne hkd_ret
    ld 0x01, x
    ld [y,x], ac
    xor 0x4E, ac
    bne hkd_ret
    ld 0x02, x
    ld [y,x], ac
    xor 0x55, ac
    bne hkd_ret
    ld 0x03, x
    ld [y,x], ac
    bne hkd_ret    ; picked from the menu: no time limit
    ld 0x04, x    ; MB_LEFT - MB_HOLD < 0: leaves sooner anyway
    ld [y,x], ac
    ld 0x0B, x
    sub [y,x], ac
    ld 0x05, x
    ld [y,x], ac
    bcc hkd_nb
    sub 1, ac
hkd_nb:
    ld 0x0C, x
    sub [y,x], ac
    blt hkd_ret
    ld 0x0B, x    ; MB_LEFT = MB_HOLD
    ld [y,x], ac
    ld 0x04, x
    ld ac, [y,x]
    ld 0x0C, x
    ld [y,x], ac
    ld 0x05, x
    ld ac, [y,x]
    bra hkd_ret

#addr 0x0500
div2:
    ; k = 3
    ld   [0x10], ac
    sub  [0x43], ac
    ld   ac, [0x13]
    ld   [0x11], ac
    bcc  ka_9
    dec
    bcs  kz_10
ka_9:
    sub  [0x44], ac
    bcc  kc_12
ky_13:
    ld   ac, [0x14]
    ld   [0x12], ac
    beq  ks_11
    clr  ac
    ld   ac, [0x12]
    ld   [0x14], ac
kc_12:
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x08, ac
    ld   ac, [0x15]
    bra  ks_11
kz_10:
    ; x1 was 0 and borrowed: t1 = FF - D_31
    ld   [0x44], ac
    not
    bra  ky_13
ks_11:
    ; k = 2
    ld   [0x10], ac
    sub  [0x40], ac
    ld   ac, [0x13]
    ld   [0x11], ac
    bcc  ka_14
    dec
    bcs  ks_16
ka_14:
    sub  [0x41], ac
    bcs  ks_16
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x04, ac
    ld   ac, [0x15]
ks_16:
    ; k = 1
    ld   [0x10], ac
    sub  [0x3D], ac
    ld   ac, [0x13]
    ld   [0x11], ac
    bcc  ka_17
    dec
    bcs  ks_19
ka_17:
    sub  [0x3E], ac
    bcs  ks_19
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x02, ac
    ld   ac, [0x15]
ks_19:
    ; k = 0
    ld   [0x10], ac
    sub  [0x3A], ac
    ld   ac, [0x13]
    ld   [0x11], ac
    bcc  ka_20
    dec
    bcs  ks_22
ka_20:
    sub  [0x3B], ac
    bcs  ks_22
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x01, ac
    ld   ac, [0x15]
ks_22:
    ld   div3 >> 8, y
    jmp  div3

#addr 0x058F
hk_poll:
    ld 0x5D, y
    ld 0x00, x
    ld [y,x], ac
    xor 0x4D, ac
    bne hkp_ret
    ld 0x01, x
    ld [y,x], ac
    xor 0x4E, ac
    bne hkp_ret
    ld 0x02, x
    ld [y,x], ac
    xor 0x55, ac
    bne hkp_ret
    ld 0x50, y    ; line read (V9:V2)
    ld [y,x], ac
    ld 0x5D, y
    ld 0x0A, x
    ld ac, [y,x]
    ld 0x06, x
    sub [y,x], ac    ; cur - last - 96 >= 0: a new frame
    sub 96, ac
    ld 0x0A, x
    blt hkp_same
    ld [y,x], ac
    ld 0x06, x
    ld ac, [y,x]
    ld 0x52, y    ; Esc: key column 0, row 0
    ld 0x00, x
    ld 0x0F, [y,x]
    nop
    nop
    nop
    nop
    ld [y,x], ac
    ld 0xFB, [y,x]
    and 1, ac
    beq hkp_esc
    ld 0x5D, y
    ld 0x03, x
    ld [y,x], ac
    bne hkp_ret    ; picked from the menu: no time limit
    ld 0x04, x
    ld [y,x], ac
    dec
    ld ac, [y,x]
    bcc hkp_ret    ; no borrow
    ld 0x05, x
    ld [y,x], ac
    dec
    ld ac, [y,x]
    blt hkp_next    ; below 0: time up
    bra hkp_ret
hkp_same:
    ld [y,x], ac
    ld 0x06, x
    ld ac, [y,x]
hkp_ret:
    ld [0x39], y
    jmp [0x38]
hkp_esc:
    ld 1, ac
    bra hkp_go
hkp_next:
    ld 2, ac
hkp_go:
    ld 0x5D, y
    ld 0x09, x
    ld ac, [y,x]
    jmp 0x20    ; the menu's exit code (RAM x5D20)

#addr 0x0600
div3:
    ; a[i] = remainder (x2 = 0)
    ld   [0x19], x
    ld   [0x1A], y
    ld   [0x10], ac
    ld   ac, [y,x]
    ld   [0x1A], ac
    add  0x0E, y
    ld   [0x11], ac
    ld   ac, [y,x]
    ; step the pointer (and i) and the five divisors down
    ld   [0x19], ac
    bne  pnz
    ld   [0x1A], ac
    dec
    ld   ac, [0x1A]
    ld   [0x18], ac
    dec
    ld   ac, [0x18]
    ; every 256 terms: check the line read for a new frame
    ld   ret_23, ac
    ld   ac, [0x32]
    ld   ret_23 >> 8, ac
    ld   ac, [0x33]
    ld   poll >> 8, y
    jmp  poll
ret_23:
    clr  ac
pnz:
    dec
    ld   ac, [0x19]
    ld   [0x3A], ac
    sub  0x02, ac
    ld   ac, [0x3A]
    bcc  dok_24
    ld   [0x3B], ac
    dec
    ld   ac, [0x3B]
dok_24:
    ld   [0x3D], ac
    sub  0x04, ac
    ld   ac, [0x3D]
    bcc  dok_25
    ld   [0x3E], ac
    dec
    ld   ac, [0x3E]
dok_25:
    ld   [0x40], ac
    sub  0x08, ac
    ld   ac, [0x40]
    bcc  dok_26
    ld   [0x41], ac
    dec
    ld   ac, [0x41]
dok_26:
    ld   [0x43], ac
    sub  0x10, ac
    ld   ac, [0x43]
    bcc  dok_27
    ld   [0x44], ac
    dec
    ld   ac, [0x44]
dok_27:
    ld   [0x46], ac
    sub  0x20, ac
    ld   ac, [0x46]
    bcc  dok_28
    ld   [0x47], ac
    dec
    ld   ac, [0x47]
    bcc  dok_28
    ld   [0x48], ac
    dec
    ld   ac, [0x48]
dok_28:
    ; loop while i > 1
    ld   [0x18], ac
    bne  again
    ld   [0x19], ac
    sub  1, ac
    beq  last
again:
    ld   inner >> 8, y
    jmp  inner
last:
    ld   last_i >> 8, y
    jmp  last_i

#addr 0x068F
init:
    ; product tables T[m][v] = m * v (low bytes at page 0x25 + m, high
    ; bytes at page 0x38 + m), built once: row m = row m - 1 + v
    clr  ac
it0:
    ld   ac, x
    ld   0x25, y
    ld   0x00, [y,x]
    ld   0x38, y
    ld   0x00, [y,x]
    inc
    bne  it0
    ld   0x25, ac
    ld   ac, [0x27]
itm:
    ld   0x00, ac
    ld   ac, [0x25]
itv:
    ld   [0x25], ac
    ld   ac, x
    ld   [0x27], y
    ld   [y,x], ac
    add  [0x25], ac
    ld   ac, [0x13]
    clr  ac
    bcc  itnc
    ld   1, ac
itnc:
    ld   ac, [0x14]
    ld   [0x27], ac
    add  0x13, y
    ld   [y,x], ac
    add  [0x14], ac
    ld   ac, [0x14]
    ld   [0x27], ac
    add  1, y
    ld   [0x13], ac
    ld   ac, [y,x]
    ld   [0x27], ac
    add  0x14, y
    ld   [0x14], ac
    ld   ac, [y,x]
    ld   [0x25], ac
    inc
    ld   ac, [0x25]
    bne  itv
    ld   [0x27], ac
    inc
    ld   ac, [0x27]
    sub  0x37, ac
    bne  itm
    ld   main >> 8, y
    jmp  main

#addr 0x06E3
clr_m:
    ; mode bytes 5A00-5BFF = 0 (1 bpp)
    ld   0x5A, y
    clr  ac
clr_m0:
    ld   ac, x
    ld   0x00, [y,x]
    inc
    bne  clr_m0
    ld   0x5B, y
clr_m1:
    ld   ac, x
    ld   0x00, [y,x]
    inc
    bne  clr_m1
    ld   tsync >> 8, y
    jmp  tsync

#addr 0x0700
show:
    ; "SSS.SSS s" centered below the digits, leading zeros as spaces
    ld   0xA9, ac
    ld   ac, [0x21]
    ld   0x60, ac
    ld   ac, [0x22]
    ld   0x00, ac
    ld   ac, [0x23]
    ld   0x00, ac
    ld   ac, [0x20]
    ; leading zeros of the seconds become spaces (the timer is cleared next)
    ld   [0x58], ac
    bne  sh1
    ld   11, ac
    ld   ac, [0x58]
    ld   [0x57], ac
    bne  sh1
    ld   11, ac
    ld   ac, [0x57]
sh1:
    ; digits 8 down to 3, with "." after the ones digit
    ld   0x58, ac
    ld   ac, [0x36]
shlp:
    ld   [0x36], x
    ld   [x], ac
    ld   ac, [0x1F]
    ld   ret_37, ac
    ld   ac, [0x28]
    ld   ret_37 >> 8, ac
    ld   ac, [0x29]
    ld   emit >> 8, y
    jmp  emit
ret_37:
    ld   [0x36], ac
    sub  0x56, ac
    bne  shnd
    ld   10, ac
    ld   ac, [0x1F]
    ld   ret_38, ac
    ld   ac, [0x28]
    ld   ret_38 >> 8, ac
    ld   ac, [0x29]
    ld   emit >> 8, y
    jmp  emit
ret_38:
shnd:
    ld   [0x36], ac
    dec
    ld   ac, [0x36]
    sub  0x52, ac
    bne  shlp
    ld   0x0B, ac
    ld   ac, [0x1F]
    ld   ret_39, ac
    ld   ac, [0x28]
    ld   ret_39 >> 8, ac
    ld   ac, [0x29]
    ld   emit >> 8, y
    jmp  emit
ret_39:
    ld   0x0C, ac
    ld   ac, [0x1F]
    ld   ret_40, ac
    ld   ac, [0x28]
    ld   ret_40 >> 8, ac
    ld   ac, [0x29]
    ld   emit >> 8, y
    jmp  emit
ret_40:
    ld   pause >> 8, y
    jmp  pause

#addr 0x0779
poll:
    ; read the line read (V9:V2, 124-255) and add one frame to the timer
    ; when it went down.  cur - last - 96 >= 0 means it wrapped, as long as
    ; polls are less than 95 steps (380 lines) apart.  Uses y and x.
    ; The menu hook first (Esc, time up: menu_hook.py).
    ld   ret_33, ac
    ld   ac, [0x38]
    ld   ret_33 >> 8, ac
    ld   ac, [0x39]
    ld   hk_poll >> 8, y
    jmp  hk_poll
ret_33:
    ld   0x50, y
    ld   [y,x], ac
    ld   ac, [0x2C]
    sub  [0x2D], ac
    sub  96, ac
    blt  pnw
    ld   0x01, ac
    ld   ac, [0x2E]
    ld   0x10, ac
    ld   ac, [0x2F]
    ld   ret_34, ac
    ld   ac, [0x34]
    ld   ret_34 >> 8, ac
    ld   ac, [0x35]
    ld   dadd >> 8, y
    jmp  dadd
ret_34:
pnw:
    ld   [0x2C], ac
    ld   ac, [0x2D]
    ld   [0x33], y
    jmp  [0x32]

#addr 0x07AC
stop:
    ; stop the timer: whole frames are counted, add the 128 us steps since
    ; the top of this frame
    ld   ret_35, ac
    ld   ac, [0x32]
    ld   ret_35 >> 8, ac
    ld   ac, [0x33]
    ld   poll >> 8, y
    jmp  poll
ret_35:
    ld   [0x2D], ac
    sub  124, ac
    ld   ac, [0x27]
    ld   0x20, ac
    ld   ac, [0x2F]
part:
    ld   [0x27], ac
    beq  pdone
    dec
    ld   ac, [0x27]
    ld   ret_36, ac
    ld   ac, [0x34]
    ld   ret_36 >> 8, ac
    ld   ac, [0x35]
    ld   dadd >> 8, y
    jmp  dadd
ret_36:
    bra  part
pdone:
    ld   show >> 8, y
    jmp  show

#addr 0x0800
pause:
    ; wait 10 s on the timer, then run the test again
    ld   ret_41, ac
    ld   ac, [0x32]
    ld   ret_41 >> 8, ac
    ld   ac, [0x33]
    ld   tclear >> 8, y
    jmp  tclear
ret_41:
pw:
    ld   ret_42, ac
    ld   ac, [0x32]
    ld   ret_42 >> 8, ac
    ld   ac, [0x33]
    ld   poll >> 8, y
    jmp  poll
ret_42:
    ld   [0x57], ac
    sub  1, ac
    bne  pw
shown:
    ; done: the menu goes on to the next program now (when rotating)
    ld   ret_43, ac
    ld   ac, [0x38]
    ld   ret_43 >> 8, ac
    ld   ac, [0x39]
    ld   hk_done >> 8, y
    jmp  hk_done
ret_43:
    ld   main >> 8, y
    jmp  main
